intentos.respuesta_cruda:
{
  "sql": "SELECT t1.product_category_name_english, AVG(t2.review_score) AS calificación_promedio, AVG(CASE WHEN t3.dias_retraso > 0 THEN 1 ELSE 0 END) AS pct_retrasos FROM product_category_translation t1 JOIN order_reviews t2 ON t2.order_id = t3.order_id JOIN vw_entregas_retrasos t3 ON t3.order_id = t2.order_id WHERE t2.review_score IS NOT NULL AND t3.dias_retraso IS NOT NULL GROUP BY t1.product_category_name_english HAVING calificación_promedio < (SELECT AVG(review_score) FROM order_reviews WHERE review_score IS NOT NULL) AND pct_retrasos < (SELECT AVG(CASE WHEN dias_retraso > 0 THEN 1 ELSE 0 END) FROM vw_entregas_retrasos WHERE dias_retraso IS NOT NULL)"
}
